        return str(len(m)) + ' ' + str(len(m[0])) + '\n' + '\n'.join(' '.join(map(str, row)) for row in m)
    def rand(r, c, lo=-9, hi=9):
        return [[rng.randint(lo, hi) for _ in range(c)] for _ in range(r)]
    tests = [fmt([[5]]), fmt([[1, 2, 3, 4]]), fmt([[1], [2], [3], [4]]), fmt([[1, 2], [3, 4]]),
