        tests.append(fmt(rand(r, c)))
    for _ in range(10):
        r = rng.randint(1, 8)
        c = rng.randint(1, 8)
        tests.append(fmt(rand(r, c)))
    tests.append(fmt(rand(316, 316, -10**9, 10**9)))
    tests.append(fmt(rand(1, 100000, -10**9, 10**9)))
    tests.append(fmt(rand(100000, 1, -10**9, 10**9)))
    tests.append(fmt(rand(100, 1000, -10**9, 10**9)))
    tests.append(fmt(rand(1000, 100, -10**9, 10**9)))
    return tests

